/**  Cites. */
"cites" | 
/**  Extends. */
"extends" | 
/**  Contradicts. */
"contradicts" | 
/**  Similar. */
"similar" | 
/**  Builds on. */
"builds_on" | 
/**  Uses the method of. */
"uses_method";

